// Нормализация ответа источника в единый формат item.
// Демо-источник: Remotive Remote Jobs API (публичный JSON).
// Формат ответа: { jobs: [ { id, title, company_name, salary, url, publication_date, ... } ] }

const sourceKey = $('Source Config').first().json.sourceKey;
const raw = $input.first().json;
const jobs = Array.isArray(raw.jobs) ? raw.jobs : [];

// Троттлинг на входе: ограничиваем объём обрабатываемых записей за прогон.
const MAX_ITEMS = 50;

const seen = new Set();
const out = [];

for (const j of jobs.slice(0, MAX_ITEMS)) {
  // externalId — стабильный идентификатор записи у источника (дедуп).
  const externalId = String(j.id ?? j.url ?? '').trim();
  if (!externalId || seen.has(externalId)) continue; // дедуп внутри одного прогона
  seen.add(externalId);

  // price: у вакансий зарплата часто строкой/пустая — приводим к числу либо null.
  let price = null;
  if (j.salary != null && String(j.salary).trim() !== '') {
    const num = String(j.salary).replace(/[^0-9.]/g, '');
    price = num ? Number(num) : null;
  }

  // fingerprint — хэш значимых полей для детекта "обновилось".
  const title = (j.title ?? '').trim();
  const company = (j.company_name ?? '').trim();
  const fpSource = [title, company, price ?? '', (j.candidate_required_location ?? '')].join('|');

  out.push({
    json: {
      sourceKey,
      externalId,
      title,
      company,
      price,
      url: (j.url ?? '').trim(),
      published_at: j.publication_date ?? null,
      fingerprint: fpSource,
    },
  });
}

if (out.length === 0) {
  throw new Error('Источник вернул 0 нормализованных записей — проверьте URL/формат API');
}

return out;

parameters.query:
SELECT external_id, title, company, price, url, fingerprint
FROM monitor_items
WHERE source_key = $1 AND is_active = true;

