// Детект изменений: сравниваем текущий прогон (Normalize Items)
// с прошлым снапшотом из БД (Load Previous Snapshot).

const current = $('Normalize Items').all().map(i => i.json);
const previous = $input.all().map(i => i.json).filter(r => r && r.external_id);

const prevById = new Map(previous.map(r => [String(r.external_id), r]));
const curById = new Map(current.map(r => [String(r.externalId), r]));

const added = [];
const changed = [];
const removed = [];

// новое и изменившееся
for (const [id, cur] of curById) {
  const prev = prevById.get(id);
  if (!prev) {
    added.push(cur);
    continue;
  }
  const prevPrice = prev.price == null ? null : Number(prev.price);
  const curPrice = cur.price == null ? null : Number(cur.price);
  const priceDropped = prevPrice != null && curPrice != null && curPrice < prevPrice;
  const fingerprintChanged = String(prev.fingerprint ?? '') !== String(cur.fingerprint ?? '');
  if (priceDropped || fingerprintChanged) {
    changed.push({
      ...cur,
      prevPrice,
      priceDropped,
      changeType: priceDropped ? 'price_drop' : 'updated',
    });
  }
}

// пропавшее (было активно, сейчас нет)
for (const [id, prev] of prevById) {
  if (!curById.has(id)) removed.push(prev);
}

const hasChanges = added.length + changed.length + removed.length > 0;

// Одиночный item с итогом — удобно для IF и Telegram.
return [{
  json: {
    sourceKey: $('Source Config').first().json.sourceKey,
    hasChanges,
    counts: { added: added.length, changed: changed.length, removed: removed.length },
    added,
    changed,
    removed,
  },
}];

// Формирование текста сводки для Telegram (только при наличии изменений).
const d = $input.first().json;
const c = d.counts;

const lines = [];
lines.push(`<b>Мониторинг: ${d.sourceKey}</b>`);
lines.push(`Новое: ${c.added} | Изменилось: ${c.changed} | Пропало: ${c.removed}`);
lines.push('');

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

if (d.added.length) {
  lines.push('<b>Новое:</b>');
  for (const j of d.added.slice(0, 10)) {
    lines.push(`+ <a href="${esc(j.url)}">${esc(j.title)}</a> — ${esc(j.company)}${j.price != null ? ' ($' + j.price + ')' : ''}`);
  }
  lines.push('');
}
if (d.changed.length) {
  lines.push('<b>Изменилось:</b>');
  for (const j of d.changed.slice(0, 10)) {
    const tag = j.changeType === 'price_drop' ? `подешевело ${j.prevPrice}→${j.price}` : 'обновилось';
    lines.push(`~ <a href="${esc(j.url)}">${esc(j.title)}</a> — ${esc(j.company)} (${tag})`);
  }
  lines.push('');
}
if (d.removed.length) {
  lines.push('<b>Пропало:</b>');
  for (const j of d.removed.slice(0, 10)) {
    lines.push(`- ${esc(j.title)} — ${esc(j.company)}`);
  }
}

return [{ json: { text: lines.join('\n') } }];
